R=[{"h": "Две семьи глаголов движения", "p": ["В русском языке 14 пар глаголов движения без приставок. Первый глагол пары — однонаправленный (одно движение в одну сторону). Второй — разнонаправленный (повторение, туда и обратно, движение вообще).", "Английские значения в таблице — цитаты из словаря OpenRussian."], "pairs": 1}, {"h": "Однонаправленные: идти́, е́хать, нести́…", "p": ["1) Движение сейчас, в одну сторону.", "2) Фон в прошлом: «шёл, когда…», движение, во время которого что-то происходит.", "3) Конкретный путь в будущем: «завтра мы едем в Москву»."], "ex": [["— Куда идёшь ты, Родя?", 3, "идёшь"], ["Он шёл и смотрел в землю.", 3, "шёл"], ["Народ бежал им навстречу.", 7, "бежал"], ["Служанка несла за нею два узла.", 7, "несла"], ["Кибитка летела по гладкому зимнему пути...", 14, "летела"], ["Она ползла в степь.", 11, "ползла"]]}, {"h": "Разнонаправленные: ходи́ть, е́здить, носи́ть…", "p": ["1) Привычка, повторение: «каждый день ходил».", "2) Туда и обратно (прошедшее): «ездил в Петербург» = был там и вернулся.", "3) Без определённого направления: «ходил по комнате».", "4) Умение, движение вообще: «не умею плавать»."], "ex": [["Он каждый день ходил в церковь и почти разучился говорить.", 6, "ходил"], ["Мы ездили к французам.", 1, "ездили"], ["Петя молча ходил по комнате.", 1, "ходил"], ["Он бродил по саду.", 4, "бродил"], ["Оглядываюсь — мы от берега около пятидесяти сажен, а я не умею плавать!", 10, "плавать"], ["Люди, крича, споря и шумя, бегали по комнатам и двору.", 1, "бегали"], ["Муха летала, она видела!", 3, "летала"]]}, {"h": "Пешком или на транспорте", "p": ["идти́/ходи́ть — пешком; е́хать/е́здить — на транспорте (карета, поезд, лошадь).", "нести́/носи́ть — в руках, пешком; везти́/вози́ть — на транспорте; вести́/води́ть — ведя за собой (человека, животное)."], "ex": [["Я привез ее в Петербург.", 6, "привез"], ["— Я и жалею, что к нему ездил и её возил,- сказал старый граф.", 1, "возил"], ["Одни из них копали лопатами гору, другие возили по доскам землю в тачках, третьи стояли, ничего не делая.", 1, "возили"], ["— Между тем молодой пастух по берегу реки гнал стадо, играя на свирели.", 12, "гнал"]]}, {"h": "Прошедшее время: шёл, ходи́л, пошёл", "p": ["шёл — был в пути (процесс, фон). ходи́л — сходил и вернулся (результат: был там). пошёл — отправился, начал движение."], "ex": [["Он пошел и вернулся.", 4, "пошел"], ["\"Я узнал, что ты вчера ночью ходила на берег\".", 10, "ходила"], ["Они пошли в сад.", 14, "пошли"]]}, {"h": "Приставки: значение и предлоги", "pref": [["в(о)-", "внутрь", "в/на + вин.", ["Пьер вошёл в кабинет.", 1, "вошёл"]], ["вы-", "наружу", "из/с + род.", ["Я вышел из кибитки.", 14, "вышел"]], ["при-", "прибытие", "в/на + вин., к + дат.", ["Я пришёл к тебе.", 3, "пришёл"]], ["у-", "уход, удаление", "из/с + род., в/на + вин.", ["Они уехали в подмосковную.", 1, "уехали"]], ["под(о)-", "приближение", "к + дат.", ["Я подошел к ней.", 6, "подошел"]], ["от(о)-", "удаление на расстояние", "от + род.", ["Наполеон кивнул головой и отошёл от него.", 1, "отошёл"]], ["пере-", "через, на другую сторону", "через + вин.", ["Раскольников перешел через площадь.", 3, "перешел"]], ["про-", "мимо, сквозь", "мимо + род., через + вин.", ["Городовой не спеша прошел мимо окон: это недаром.", 9, "прошел"]], ["до-", "до предела, до цели", "до + род.", ["Они насилу дошли до конца сада.", 7, "дошли"]], ["за-", "зайти по пути, за чем-то", "к + дат., в + вин., за + твор.", ["Я зашел к нему; он сложа руки прохаживался угрюмый взад и вперед.", 10, "зашел"]], ["об(о)-", "вокруг", "вин. (без предлога), вокруг + род.", ["Я покинул мою засаду и обошел весь сад.", 17, "обошел"]], ["с(о)-", "вниз, с поверхности", "с + род.", ["Пугачев сошел с крыльца.", 14, "сошел"]], ["по-", "начало движения", "в/на + вин., к + дат.", ["Я пошел к нему.", 14, "пошел"]]]}, {"h": "Приставка → вид", "p": ["Приставка + однонаправленный = совершенный вид: прийти́, вы́нести, уе́хать.", "Приставка + разнонаправленный = несовершенный вид: приходи́ть, выноси́ть, уезжа́ть.", "Внимание к основам: -езжа́ть (не «-ездить»), -бега́ть, -плыва́ть, -леза́ть, -таскивать, -гоня́ть. Ударение в -бега́ть падает на окончание: прибега́ть.", "По- + однонаправленный — только совершенный вид (пойти́, пое́хать, понести́): «отправиться»."], "ex": [["Он приехал в *** ревизовать губернию.", 2, "приехал"], ["Зачем ты прежде не приходил?", 3, "приходил"], ["Я бродил по городу; возвращался домой, выходил снова.", 6, "выходил"]]}, {"h": "Повелительное наклонение", "p": ["иди́ / ходи́ — обе формы живые. От е́хать нет литературной формы «ехай»: говорят поезжа́й, езжа́й."], "ex": [["— Вы поезжайте в Петербург; это лучше.", 1, "поезжайте"], ["\"Поезжай, матушка!\" — сказал он ей со вздохом.", 14, "Поезжай"]]}, {"h": "Переносные значения", "p": ["Глаголы движения часто живут без движения: дождь идёт, время идёт, дело идёт о…, вести себя, носить (одежду, усы), везёт (кому-то), идёт (кому-то = к лицу), сойти с ума, водить за нос."], "ex": [["Дождь шел, ветер выл громко.", 11, "шел"], ["Помни, Илья, мы не дети и не шутим: дело идет о целой жизни!", 4, "идет"], ["Между тем время прошло незаметно.", 14, "прошло"], ["Сын ведет себя крайне бестактно.", 8, "ведет"], ["Не везет мне сегодня.", 20, "везет"], ["И как это к тебе идёт, если б ты знал; Ромео десяти вершков росту!", 3, "идёт"], ["Ты сошел с ума!", 8, "сошел"], ["Другое дело, если б я носил эполеты...", 10, "носил"], ["Каменистая тропинка вела к уцелевшим воротам.", 6, "вела"]]}, {"h": "Орфография", "p": ["Пишем прийти́ (не «придти»), но приду́, пришёл.", "С приставкой на согласный перед -йти появляется о: войти́, подойти́, отойти́, обойти́, сойти́.", "Перед е́хать после твёрдой приставки — ъ: въе́хать, подъе́хать, отъе́хать, объе́хать, съе́здить.", "В старых изданиях ё обычно пишется как е: шел = шёл. В приложении ё и е считаются одной буквой."]}],
FIRST=["В начале июля, в чрезвычайно жаркое время, под вечер, один молодой человек вышел из своей каморки, которую нанимал от жильцов в С — м переулке, на улицу и медленно, как бы в нерешимости, отправился к К — ну мосту.", 3, "вышел"];
